import org.jsoup.helper.W3CDom;
import org.junit.Test;
import static org.junit.Assert.*;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.dom.DOMSource;

public class W3CDomTest {

    @Test
    public void namespaceAware_ReturnsTrue() {
        boolean result = new W3CDom().namespaceAware();
        assertTrue(result);
    }

    @Test
    public void namespaceAware_SetReturnsNewObject() {
        W3CDom obj1 = new W3CDom();
        W3CDom obj2 = new W3CDom(obj1.namespaceAware());
        assertFalse(obj1.namespaceAware());
        assertTrue(obj2.namespaceAware());
    }

    @Test
    public void convert_ConvertsDocument() throws Exception {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        doc.getDocumentElement().setTagName("root");
        StringWriter writer = new StringWriter();
        Transformer transformer = TransformerFactory.newInstance().newTransformer();
        DOMSource source = new DOMSource(doc);
        StreamResult result = new StreamResult(writer);
        transformer.transform(source, result);
        String xml = writer.toString();
        assertEquals("<root></root>", xml);
    }

    @Test
    public void convert_ConvertsEmptyDocument() throws Exception {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        StringWriter writer = new StringWriter();
        Transformer transformer = TransformerFactory.newInstance().newTransformer();
        DOMSource source = new DOMSource(doc);
        StreamResult result = new StreamResult(writer);
        transformer.transform(source, result);
        String xml = writer.toString();
        assertTrue(xml.isEmpty());
    }

    @Test
    public void propertiesFromMap_CreatesProperties() {
        Map<String, String> map = new HashMap<>();
        map.put("namespace", "http://example.com");
        Properties props = W3CDom.propertiesFromMap(map);
        assertNotNull(props);
        assertEquals("http://example.com", props.getProperty("namespace"));
    }

    @Test
    public void OutputHtml_RetursDictionary() {
        Map<String, String> result = W3CDom.OutputHtml();
        assertNotNull(result);
        assertTrue(result.containsKey("doctype"));
        assertTrue(result.containsKey("encoding"));
        assertTrue(result.containsKey("xmlversion"));
        assertEquals("<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">", result.get("doctype"));
    }

    @Test
    public void OutputXml_RetursDictionary() {
        Map<String, String> result = W3CDom.OutputXml();
        assertNotNull(result);
        assertTrue(result.containsKey("doctype"));
        assertTrue(result.containsKey("encoding"));
        assertTrue(result.containsKey("xmlversion"));
        assertEquals("<?xml version=\"1.0\" encoding=\"UTF-8\" ?>", result.get("doctype"));
    }

    @Test
    public void fromJsoup_ConvertsDocument() throws Exception {
        Document doc = W3CDom.fromJsoup(new org.jsoup.nodes.Document());
        assertNotNull(doc);
    }

    @Test
    public void fromJsoup_ConvertsEmptyElement() throws Exception {
        Element elem = new org.jsoup.nodes.Element();
        Document doc = W3CDom.fromJsoup(elem);
        assertNotNull(doc);
    }

    @Test
    public void convert_ConvertsDocument() {
        org.jsoup.nodes.Document in = new org.jsoup.nodes.Document();
        Document out = new W3CDom().convert(in, null);
        assertNull(out);
    }

    @Test
    public void selectXpath_RetursNullListWhenEmpty() throws Exception {
        NodeList nodeList = W3CDom.selectXpath("", new org.jsoup.nodes.Document());
        assertTrue(nodeList.getLength() == 0);
    }

    @Test
    public void selectXpath_RetursNonNullListWhenPresent() throws Exception {
        String xpath = "//div";
        NodeList nodeList = W3CDom.selectXpath(xpath, new org.jsoup.nodes.Document());
        assertNotNull(nodeList);
        assertEquals(1, nodeList.getLength());
    }

    @Test
    public void sourceNodes_ReturnsNonNullList() {
        NodeList nodeList = new org.jsoup.nodes.NodeList();
        List<org.jsoup.nodes.Node> result = W3CDom.sourceNodes(nodeList, org.jsoup.nodes.Node.class);
        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void contextNode_ReturnsNonNullNode() {
        Document wDoc = new org.jsoup.nodes.Document();
        Node node = W3CDom.contextNode(wDoc);
        assertNotNull(node);
    }

    @Test
    public void asString_RetursNonNullString() throws Exception {
        Document doc = new org.jsoup.nodes.Document();
        doc.getDocumentElement().setTagName("root");
        String result = W3CDom.asString(doc, null);
        assertNotNull(result);
        assertEquals("<root></root>", result);
    }

    @Test
    public void asString_ReturnsEmptyStringWhenEmpty() throws Exception {
        Document doc = new org.jsoup.nodes.Document();
        StringWriter writer = new StringWriter();
        Transformer transformer = TransformerFactory.newInstance().newTransformer();
        DOMSource source = new DOMSource(doc);
        StreamResult result = new StreamResult(writer);
        transformer.transform(source, result);
        String xml = writer.toString();
        assertFalse(xml.isEmpty());
    }

}
